(window.__qhadithX=window.__qhadithX||{})[98]={"1":[{"c":"Sahih Muslim","r":"Hadith 799b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-799b","x":"Anas reported Allah's Messenger (ﷺ) as saying to Ubayy b. Ka`b:\n\nAllah has commanded me to recite to you:\" Those who disbelieve were not...\" (al-Qur'an, xcviii. 1). He said: Did He mention me by name? He (the Prophet said): Yes. Upon this he shed tears (of gratitude).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، قَالَ سَمِعْتُ قَتَادَةَ، يُحَدِّثُ عَنْ أَنَسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأُبَىِّ بْنِ كَعْبٍ ‏\"‏ إِنَّ اللَّهَ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ ‏{‏ لَمْ يَكُنِ الَّذِينَ كَفَرُوا‏}‏ ‏\"‏ ‏.‏ قَالَ وَسَمَّانِي لَكَ قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ قَالَ فَبَكَى ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3792","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3792","x":"Narrated Anas bin Malik:\n\nthat the Messenger of Allah (ﷺ) said to Ubayy bin Ka'b: \"Indeed Allah ordered me to recite to you: Those who disbelieve were not going to... (98:1) He said: \"And He named me?\" He said: \"Yes.\" So he wept.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، قَالَ حَدَّثَنَا شُعْبَةُ، قَالَ سَمِعْتُ قَتَادَةَ، يُحَدِّثُ عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأُبَىِّ بْنِ كَعْبٍ ‏\"‏ إِنَّ اللَّهَ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ ‏:‏ ‏(‏ لَمْ يَكُنِ الَّذِينَ كَفَرُوا ‏)‏ ‏\"‏ ‏.‏ قَالَ وَسَمَّانِي قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ فَبَكَى ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ عَنْ أُبَىِّ بْنِ كَعْبٍ قَالَ قَالَ لِيَ النَّبِيُّ صلى الله عليه وسلم فَذَكَرَ نَحْوَهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3898","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3898","x":"Narrated Ubayy bin Ka'b:\n\nthat the Messenger of Allah (ﷺ) said to him: \"Indeed Allah has ordered me to recite the Qur'an to you.\" So he recited to him: \"Those who disbelieved were not going to... (98:1) and he recited in it: \"Indeed the religion with Allah is that which is Hanafiyyah, Muslim, not Judaism, nor Christianity, nor Zoroastrian, whoever does good then it shall not be rejected from him.\" And he recited to him: \"If the son of Adam had a valley of wealth he would seek a second, and if he had a second he would seek a third, and nothing fills the belly of the son of Adam except dirt. And Allah pardons those who repent.\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، قَالَ حَدَّثَنَا أَبُو دَاوُدَ، قَالَ أَخْبَرَنَا شُعْبَةُ، عَنْ عَاصِمٍ، قَالَ سَمِعْتُ زِرَّ بْنَ حُبَيْشٍ، يُحَدِّثُ عَنْ أُبَىِّ بْنِ كَعْبٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ لَهُ ‏\"‏ إِنَّ اللَّهَ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ الْقُرْآنَ ‏\"‏ ‏.‏ فَقَرَأَ عَلَيْهِ ‏:‏ ‏(‏ لمْ يَكُنِ الَّذِينَ كَفَرُوا ‏)‏ وَفِيهَا ‏\"‏ إِنَّ ذَاتَ الدِّينِ عِنْدَ اللَّهِ الْحَنِيفِيَّةُ الْمُسْلِمَةُ لاَ الْيَهُودِيَّةُ وَلاَ النَّصْرَانِيَّةُ وَلاَ الْمَجُوسِيَّةُ مَنْ يَعْمَلْ خَيْرًا فَلَنْ يُكْفَرَهُ ‏\"‏ ‏.‏ وَقَرَأَ عَلَيْهِ ‏\"‏ لَوْ أَنَّ لاِبْنِ آدَمَ وَادِيًا مِنْ مَالٍ لاَبْتَغَى إِلَيْهِ ثَانِيًا وَلَوْ كَانَ لَهُ ثَانِيًا لاَبْتَغَى إِلَيْهِ ثَالِثًا وَلاَ يَمْلأُ جَوْفَ ابْنِ آدَمَ إِلاَّ التُّرَابُ وَيَتُوبُ اللهُ عَلَى مَنْ تَابَ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ مِنْ غَيْرِ هَذَا الْوَجْهِ رَوَاهُ عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى عَنْ أَبِيهِ عَنْ أُبَىِّ بْنِ كَعْبٍ رضى الله عنه أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لَهُ ‏\"‏ إِنَّ اللَّهَ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ الْقُرْآنَ ‏\"‏ ‏.‏ وَقَدْ رَوَاهُ قَتَادَةُ عَنْ أَنَسٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لأُبَىِّ بْنِ كَعْبٍ ‏\"‏ إِنَّ اللَّهَ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ الْقُرْآنَ ‏\"‏ ‏.‏","v":[]}]};